    {
      "keystrokes": "sed -n '104,140p' skill_context/SKILL.md\\n",
      "duration": 0.5
    },
    {
      "keystrokes": "sed -n '450,500p' skill_context/SKILL.md\\n",
      "duration": 0.5
    }
  ]
}

